#include "stdafx.h"#include "SM_RemoteClient.h"#include <SetDataTypes.h>#include <Connect.h>#include <RsuX.h>#include <rsuNoNames.h>#include "SMsPool.h"LPCSTR g_szPntsFilePrefix = "РСУ_SMH_";bool GetFirstACSObject( );bool GetNextACSObject( DWORD & Type, void ** pData, char Name[256], char Info[256] );bool ShowACSObject( void * pInfo, HWND hMainWnd, char * Name, void * pData );nRSUx::SParamInfo RsuConnectParamInfo( LPCSTR pszPointName, LPSTR pszIOtype, LPCSTR pSuffix );static bool bRegisteredFind = false;extern KSMsPool g_Pool;KNoName g_IOs;KSM_RemoteClient::KSM_RemoteClient( LPSTR _ObjName ) :	IBaseModel ( _ObjName ), m_nAcsFindStep( 0 ){  TypeObj = RSU_Obj;  size_t prefixLen = strlen(g_szPntsFilePrefix);  LPCSTR pszRealName = _ObjName;  if( !_strnicmp( _ObjName, g_szPntsFilePrefix, prefixLen) )    pszRealName += prefixLen;  strcpy_s( m_szRealName, pszRealName );}LPCSTR KSM_RemoteClient::GetName(){  return ObjName;}int KSM_RemoteClient::Init( int ){#ifdef _DEBUG  int r = KRsuSharedClient::InitializeServer( "SafetyManagerH5xx_Server", ObjName, true );#else  int r = KRsuSharedClient::InitializeServer( "SafetyManagerH5xx_Server", ObjName );#endif  if( r )    return 1;  if( pRegisterFinderACSobj && !bRegisteredFind )  {    bRegisteredFind = true;    pRegisterFinderACSobj( ::GetFirstACSObject, ::GetNextACSObject, ::ShowACSObject);    //g_IOs = KNoName::Create( "SM5xx_IOs", false );  }  // VM: 17.10.2023  g_IOs = KNoName::Create( "SM5xx_IOs", false );  if( pRegisterRsuConnection )    pRegisterRsuConnection( g_szPntsFilePrefix, RsuConnectParamInfo, NULL );  g_Pool.RegisterSM( this );  return 0;}int KSM_RemoteClient::Step0(){  return KRsuSharedClient::StepAfterInit();}int KSM_RemoteClient::Step1(){  return KRsuSharedClient::StepAfterRestored();}int KSM_RemoteClient::StepT(double dt){  int nStep = 0;  double dtMs = dt * 3600. * 1000;  return KRsuSharedClient::CalcStep( (int)dtMs );}int KSM_RemoteClient::SetData( int TypeData, void * pData ){  switch( TypeData )  {  case sd_SaveRSUParams:    return KRsuSharedClient::ParamsSave( (LPCSTR)pData );  case sd_RestoreRSUParams:    return KRsuSharedClient::ParamsRestore( (LPCSTR)pData );  case sd_SaveRSUState:    return KRsuSharedClient::StateSave( (LPCSTR)pData );  case sd_RestoreRSUState:    return KRsuSharedClient::StateRestore( (LPCSTR)pData );  default:    return -1;  }  return 0;}